namespace Logistix.GUI.Winforms.Forms

{

    public partial class SplashForm : Telerik.WinControls.UI.RadForm

    {

        private IJobViewModel _jobViewModel;

        private ITarriffViewModel _tarriffViewModel;

        private IAccountViewModel _accountViewModel;



        public SplashForm(IJobViewModel jobViewModel, ITarriffViewModel tarriffViewModel, IAccountViewModel accountViewModel)

        {

            InitializeComponent();

            _jobViewModel = jobViewModel;

            _tarriffViewModel = tarriffViewModel;

            _accountViewModel = accountViewModel;

            StartPosition = FormStartPosition.CenterScreen;

            btnRetry.Click

            Shown += OnShownAsync;

        }



        public static IServiceProvider ServiceProvider { get; set; }



        private async void OnShownAsync(object sender, EventArgs e)

        {

            await SplashForm_LoadAsync();

        }



        private async Task SplashForm_LoadAsync()

        {

            this.labelVersion.Text = $"Version {Application.ProductVersion}";



            // initialize progress

            SetProgress(0);



            // Start all loads concurrently (do not await here)

            var tAccount = LoadAccountData();    // loads AccountsCacheObject.CustomerAccountCollection

            var tShipper = LoadShipperData();    // loads AccountsCacheObject.ShipperAccountCollection

            var tConsignee = LoadConsigneeData();// loads AccountsCacheObject.ConsigneeAccountCollection

            var tRateTables = LoadRateTables();  // loads JobCacheGlobalObject.RateTableCollection



            var tPendingJobs = LoadPendingJobs(); // loads JobCacheGlobalObject.PendingJobCollection

            var tProcessingJobs = LoadProcessingJobs(); // loads JobCacheGlobalObject.ProcessingJobCollection

            var tInRouteJobs = LoadInRouteJobs(); // loads JobCacheGlobalObject.InRouteJobCollection

            var tAbandonedJobs = LoadAbandonedJobs(); // loads JobCacheGlobalObject.AbandonedJobcollection

            var tCompleteJobs = LoadCompleteJobs(); // loads JobCacheGlobalObject.CompleteJobCollection

            var tOnHoldJobs = LoadOnHoldJobs(); // loads JobCacheGlobalObject.CompleteJobCollection



            var tasks = new List<Task> { tAccount, tShipper, tConsignee, tRateTables, tPendingJobs, tProcessingJobs, tInRouteJobs, tAbandonedJobs, tCompleteJobs, tOnHoldJobs };



            // Wait until every load finishes; if any load throws, we'll catch and stop navigation.

            try

            {

                await Task.WhenAll(tasks);

            }

            catch (Exception ex)

            {

                // Show error and keep the splash open (do not proceed to main).

                radLabel2.Text = "Error connecting to Server: ";

                btnRetry.Visible = true;



                return;

            }



            // Ensure indicator reaches 100 (in case of rounding)

            SetProgress(100);



            // Small delay can help UI reflect the final progress update

            await Task.Delay(50);



            // All loads done — show main UI

            var main = new MainToolBar();

            main.Show();



            Hide(); // keep the app running

            main.FormClosed += (_, _) => Close();

        }



        /// <param name="value">0..100</param>

        private void SetProgress(int value)

        {

            if (value < 0) value = 0;

            if (value > 100) value = 100;



            Action updateAction = () =>

            {

                try

                {

                    // Update numeric value

                    if (this.radProgressBar1 != null)

                    {

                        this.radProgressBar1.Value1 = value;



                        // Try updating text to show percentage if supported

                        try

                        {

                            this.radProgressBar1.Text = $"{value}%";

                        }

                        catch

                        {

                            // Some RadProgressBar setups may not expose Text; ignore if not available.

                        }

                    }

                }

                catch

                {

                    // Swallow UI update exceptions to avoid crashing splash

                }

            };



            if (this.radProgressBar1 != null && this.radProgressBar1.InvokeRequired)

            {

                this.radProgressBar1.BeginInvoke(updateAction);

            }

            else

            {

                updateAction();

            }

        }



        private async Task LoadPendingJobs()

        {

            var accountResults = await _jobViewModel.GetIncomingJobs();

            if (accountResults == null) throw new InvalidOperationException("GetIncomingJobs returned null");

            if (!accountResults.Success) throw new InvalidOperationException($"GetIncomingJobs failed: {accountResults.Message}");

