using Logistix.GUI.Winforms.ViewModels.Context.Tarriff;
using Telerik.WinControls.UI;

namespace Logistix.GUI.Winforms.Forms
{
    public partial class SplashForm : RadForm
    {
        private readonly IJobViewModel _jobViewModel;
        private readonly ITarriffViewModel _tarriffViewModel;
        private readonly IAccountViewModel _accountViewModel;
        private bool _isLoading;

        public SplashForm(
            IJobViewModel jobViewModel,
            ITarriffViewModel tarriffViewModel,
            IAccountViewModel accountViewModel)
        {
            InitializeComponent();
            _jobViewModel = jobViewModel;
            _tarriffViewModel = tarriffViewModel;
            _accountViewModel = accountViewModel;

            StartPosition = FormStartPosition.CenterScreen;
            btnRetry.Visible = false;
            btnRetry.Click += BtnRetry_Click;
            Shown += OnShown;
        }

        private async void OnShown(object sender, EventArgs e)
        {
            Shown -= OnShown;
            await LoadAllAsync();
        }

        private async void BtnRetry_Click(object sender, EventArgs e)
        {
            btnRetry.Visible = false;
            radLabel2.Text = "";
            SetProgress(0);
            await LoadAllAsync();
        }

        private async Task LoadAllAsync()
        {
            if (_isLoading) return;
            _isLoading = true;

            SetProgress(0);

            try
            {
                // 1) Quick health check with 5s timeout
                await EnsureApiUpAsync();

                // 2) Kick off all loads in parallel
                var tasks = new List<Task>
                {
                    LoadAccountData(),
                    LoadShipperData(),
                    LoadConsigneeData(),
                    LoadRateTables(),
                    LoadPendingJobs(),
                    LoadProcessingJobs(),
                    LoadInRouteJobs(),
                    LoadAbandonedJobs(),
                    LoadCompleteJobs(),
                    LoadOnHoldJobs()
                };

                await Task.WhenAll(tasks);

                // 3) Finalize
                SetProgress(100);
                await Task.Delay(50);

                var main = new MainToolBar();
                main.Show();
                Hide();
                main.FormClosed += (_, _) => Close();
            }
            catch (Exception ex)
            {
                radLabel2.Text = $"Unable to connect to server: {ex.Message}";
                btnRetry.Visible = true;
            }
            finally
            {
                _isLoading = false;
            }
        }

        private async Task EnsureApiUpAsync()
        {
            // call a lightweight endpoint (GetAccounts) with timeout
            var healthTask = _accountViewModel.GetAccountsAsync();
            var timeoutTask = Task.Delay(TimeSpan.FromSeconds(5));

            var completed = await Task.WhenAny(healthTask, timeoutTask);
            if (completed == timeoutTask)
                throw new TimeoutException("Server did not respond in time.");

            var result = await healthTask;
            if (result == null || !result.Success)
                throw new InvalidOperationException(result?.Message ?? "Health check failed.");
        }

        private void SetProgress(int value)
        {
            if (value < 0) value = 0;
            if (value > 100) value = 100;

            Action update = () =>
            {
                try
                {
                    radProgressBar1.Value1 = value;
                    radProgressBar1.Text = $"{value}%";
                }
                catch { /* ignore UI quirks */ }
            };

            if (radProgressBar1.InvokeRequired)
                radProgressBar1.BeginInvoke(update);
            else
                update();
        }

        // -- Cache-loading methods (unchanged) --

        private async Task LoadAccountData()
        {
            var res = await _accountViewModel.GetAccountsAsync();
            if (res == null || !res.Success) throw new InvalidOperationException(res?.Message);
            AccountsCacheObject.CustomerAccountCollection = res.RecordsetCollection ?? new List<CustomerDTO>();
            AccountsCacheObject.CustomerAccountDropDownCollection = AccountsCacheObject.CustomerAccountCollection;
        }

        private async Task LoadShipperData()
        {
            var res = await _accountViewModel.GetShippersAsync();
            if (res == null || !res.Success) throw new InvalidOperationException(res?.Message);
            AccountsCacheObject.ShipperAccountCollection = res.RecordsetCollection ?? new List<ShipperDto>();
            AccountsCacheObject.ShipperAccountDropDownCollection = AccountsCacheObject.ShipperAccountCollection;
        }

        private async Task LoadConsigneeData()
        {
            var res = await _accountViewModel.GetConsigneeAsync();
            if (res == null || !res.Success) throw new InvalidOperationException(res?.Message);
            AccountsCacheObject.ConsigneeAccountCollection = res.RecordsetCollection ?? new List<ConsigneeDto>();
            AccountsCacheObject.ConsigneeAccountDropDownCollection = AccountsCacheObject.ConsigneeAccountCollection;
        }

        private async Task LoadRateTables()
        {
            var res = await _tarriffViewModel.GetRateTables();
            if (res == null || !res.Success) throw new InvalidOperationException(res?.Message);
            JobCacheGlobalObject.RateTableCollection = res.RecordsetCollection ?? new List<RateTableDto>();
        }

        private async Task LoadPendingJobs()
        {
            var res = await _jobViewModel.GetIncomingJobs();
            if (res == null || !res.Success) throw new InvalidOperationException(res?.Message);
            JobCacheGlobalObject.PendingJobCollection = res.RecordsetCollection ?? new List<JobDto>();
        }

        private async Task LoadProcessingJobs()
        {
            var res = await _jobViewModel.GetProcessingJobs();
            if (res == null || !res.Success) throw new InvalidOperationException(res?.Message);
            JobCacheGlobalObject.ProcessingJobCollection = res.RecordsetCollection ?? new List<JobDto>();
        }

        private async Task LoadInRouteJobs()
        {
            var res = await _jobViewModel.GetInRouteJobs();
            if (res == null || !res.Success) throw new InvalidOperationException(res?.Message);
            JobCacheGlobalObject.InRouteJobCollection = res.RecordsetCollection ?? new List<JobDto>();
        }

        private async Task LoadAbandonedJobs()
        {
            var res = await _jobViewModel.GetAbandonedJobs();
            if (res == null || !res.Success) throw new InvalidOperationException(res?.Message);
            JobCacheGlobalObject.AbandonedJobcollection = res.RecordsetCollection ?? new List<JobDto>();
        }

        private async Task LoadCompleteJobs()
        {
            var res = await _jobViewModel.GetCompleteJobs();
            if (res == null || !res.Success) throw new InvalidOperationException(res?.Message);
            JobCacheGlobalObject.CompleteJobCollection = res.RecordsetCollection ?? new List<JobDto>();
        }

        private async Task LoadOnHoldJobs()
        {
