                    radProgressBar1.Value1 = pct;
                    radProgressBar1.Text   = $"{pct}%";
                }
                catch { }
            };

            if (radProgressBar1.InvokeRequired)
                radProgressBar1.BeginInvoke(upd);
            else
                upd();
        }

        // -- unchanged cache-loading methods:

