using System;

using System.Threading;

using Logistix.Domain.Models.Infrastructure;

using Microsoft.AspNetCore.SignalR.Client;

using Serilog;

using System.Reactive.Subjects;

using System.Reactive.Linq;



namespace Logistix.ApplicationLayer.UseCase.Watchdog

{

    public static class WatchdogObject

    {

        // subscriptions

        private static IDisposable? _vehicleSub;

        private static IDisposable? _jobSub;

        private static IDisposable? _dbSub;

        private static IDisposable? _podSub;

        private static IDisposable? _stateSub;



        // reactive subject for connection state

        private static readonly Subject<HubConnectionState> _connectionStateSubject = new();



        // latest values (nullable)

        public static MessageModel? LatestVehicleUpdate { get; private set; }

        public static MessageModel? LatestJobUpdate { get; private set; }

        public static MessageModel? LatestDatabaseUpdate { get; private set; }

        public static MessageModel? LatestProofOfDelivery { get; private set; }



        public static HubConnectionState CurrentConnectionState { get; private set; } = HubConnectionState.Disconnected;



        // events for consumers who prefer events over observables (DataReceived removed)

        public static event Action<MessageModel?>? VehicleUpdateReceived;

        public static event Action<MessageModel?>? JobUpdateReceived;

        public static event Action<MessageModel?>? DatabaseUpdateReceived;

        public static event Action<MessageModel?>? ProofOfDeliveryReceived;

        public static event Action<HubConnectionState>? ConnectionStateChanged;



        // expose connection state as an IObservable

        public static IObservable<HubConnectionState> ConnectionStateStream => _connectionStateSubject.AsObservable();



        private static readonly object _sync = new();





        public static void RegisterVehicleUpdates(IObservable<MessageModel> stream)

        {

            lock (_sync)

            {

                _vehicleSub?.Dispose();

                _vehicleSub = stream.Subscribe(

                    msg =>

                    {

                        LatestVehicleUpdate = msg;

                        VehicleUpdateReceived?.Invoke(msg);

                    },

                    ex => Log.Warning(ex, "Watchdog: VehicleUpdateStream faulted"),

                    () => Log.Information("Watchdog: VehicleUpdateStream completed")

                );

            }

        }



        public static void RegisterJobUpdates(IObservable<MessageModel> stream)

        {

            lock (_sync)

            {

                _jobSub?.Dispose();

                _jobSub = stream.Subscribe(

                    msg =>

                    {

                        LatestJobUpdate = msg;

                        JobUpdateReceived?.Invoke(msg);

                    },

                    ex => Log.Warning(ex, "Watchdog: JobUpdateStream faulted"),

                    () => Log.Information("Watchdog: JobUpdateStream completed")

                );

            }

        }



        public static void RegisterDatabaseUpdates(IObservable<MessageModel> stream)

        {

            lock (_sync)

            {

                _dbSub?.Dispose();

                _dbSub = stream.Subscribe(

                    msg =>

                    {

                        LatestDatabaseUpdate = msg;

                        DatabaseUpdateReceived?.Invoke(msg);

                    },

                    ex => Log.Warning(ex, "Watchdog: DatabaseUpdateStream faulted"),

                    () => Log.Information("Watchdog: DatabaseUpdateStream completed")

                );

            }

        }



        public static void RegisterProofOfDelivery(IObservable<MessageModel> stream)

        {

            lock (_sync)

            {

                _podSub?.Dispose();

                _podSub = stream.Subscribe(

                    msg =>

                    {

                        LatestProofOfDelivery = msg;

                        ProofOfDeliveryReceived?.Invoke(msg);

                    },

                    ex => Log.Warning(ex, "Watchdog: ProofOfDeliveryStream faulted"),

                    () => Log.Information("Watchdog: ProofOfDeliveryStream completed")

                );

            }

        }



        public static void RegisterConnectionState(IObservable<HubConnectionState> stateStream)

        {

            lock (_sync)

            {

                _stateSub?.Dispose();

                _stateSub = stateStream.Subscribe(

                    s =>

                    {

                        CurrentConnectionState = s;

                        // publish to observable subscribers

                        try { _connectionStateSubject.OnNext(s); } catch { /* ignore */ }

                        ConnectionStateChanged?.Invoke(s);

                    },

                    ex => Log.Warning(ex, "Watchdog: ConnectionStateStream faulted"),

                    () => Log.Information("Watchdog: ConnectionStateStream completed")

                );

            }

        }



        public static void UnregisterAll()

        {

            lock (_sync)

            {

                try

                {

                    _dataSub?.Dispose();

                    _vehicleSub?.Dispose();

                    _jobSub?.Dispose();

                    _dbSub?.Dispose();

                    _podSub?.Dispose();

                    _stateSub?.Dispose();

                    // do not complete _connectionStateSubject so late subscribers can still observe future state if re-registered

                }

                catch (Exception ex)

                {

                    Log.Warning(ex, "Watchdog: UnregisterAll encountered an error while disposing subscriptions");

                }

                finally

                {

                    _dataSub = _vehicleSub = _jobSub = _dbSub = _podSub = _stateSub = null;

                }

            }

        }

    }

