public ReturnPackage<ZonePricingRuleDto> GetMatchingPricingRule(JobDto jobDto, RateTableZoneDto pricingZone)
{
    // 1) inputs
    var pickupDate    = jobDto.JobDetails.PickupDate;
    var deliveryDate  = jobDto.JobDetails.DeliveryDate;
    var pickupDay     = pickupDate.DayOfWeek.ToString();
    var deliveryDay   = deliveryDate.DayOfWeek.ToString();
    var pickupTime    = jobDto.JobDetails.PickupTime;
    var deliveryTime  = jobDto.JobDetails.DeliveryTime;
    var isLongTerm    = jobDto.JobDetails.LongTermStorage;

    // 2) perfect-match predicate
    bool DateWindow(ZonePricingRuleDto r) =>
        r.ValidStartDate <= pickupDate
        && (isLongTerm || r.ValidEndDate >= deliveryDate);

    bool DayMatch(ZonePricingRuleDto r) =>
        r.OnDays
         .Split(',', StringSplitOptions.RemoveEmptyEntries)
         .Select(d => d.Trim())
         .Contains(pickupDay, StringComparer.OrdinalIgnoreCase)
        && (isLongTerm
            || r.OnDays
                .Split(',', StringSplitOptions.RemoveEmptyEntries)
                .Select(d => d.Trim())
                .Contains(deliveryDay, StringComparer.OrdinalIgnoreCase));

    bool TimeMatch(ZonePricingRuleDto r)
    {
        var pOk = !pickupTime.HasValue
                  || (r.ValidHoursStart <= pickupTime.Value && pickupTime.Value <= r.ValidHoursEnd);
        var dOk = isLongTerm
                  || !deliveryTime.HasValue
                  || (r.ValidHoursStart <= deliveryTime.Value && deliveryTime.Value <= r.ValidHoursEnd);
        return pOk && dOk;
    }

    // 3) find perfect
    var perfect = pricingZone.ZonePricingRuleCollection
        .FirstOrDefault(r => DateWindow(r) && DayMatch(r) && TimeMatch(r));

    // 4) fallback by highest Position
    var fallback = pricingZone.ZonePricingRuleCollection
        .OrderByDescending(r => r.Position)
        .FirstOrDefault();

    var chosen = perfect ?? fallback;

    // 5) return
    return new ReturnPackage<ZonePricingRuleDto>
    {
        Success   = perfect != null,
        RecordSet = chosen,
        Message   = perfect != null
            ? "Perfect match found"
            : (fallback != null
                ? $"No perfect match; using fallback rule (Position={fallback.Position})"
                : "No pricing rules available")
    };
}
