    {
        if (pickupTime is TimeOnly p &&
            (p < r.ValidHoursStart || p > r.ValidHoursEnd))
        {
            return false;
        }
        if (!isLongTerm &&
            deliveryTime is TimeOnly d &&
            (d < r.ValidHoursStart || d > r.ValidHoursEnd))
        {
            return false;
        }
        return true;
    }

    // 3) stage 1: filter by date window
    var dateMatches = pricingZone.ZonePricingRuleCollection
        .Where(DateWindow)
        .ToList();

    // 4) stage 2: filter by day-of-week
    var dayMatches = dateMatches
        .Where(DayMatch)
        .ToList();

    // 5) stage 3: filter by time window
    var timeMatches = dayMatches
        .Where(TimeMatch)
        .ToList();

    // 6) pick the single rule left (or fallback if more than one)
    var finalSet = timeMatches.Any()
        ? timeMatches
        : dayMatches.Any()
            ? dayMatches
            : dateMatches;

    return finalSet
        .OrderByDescending(r => r.Position)
        .FirstOrDefault();
}
```

```csharp
public ZonePricingRuleDto GetMatchingPricingRule(JobDto jobDto, RateTableZoneDto pricingZone)
{
    // 1) inputs
    var pickupDate    = jobDto.JobDetails.PickupDate;
    var deliveryDate  = jobDto.JobDetails.DeliveryDate;
    var pickupDay     = pickupDate.DayOfWeek.ToString();
    var deliveryDay   = deliveryDate.DayOfWeek.ToString();
    TimeOnly? pickupTime   = jobDto.JobDetails.PickupTime;
    TimeOnly? deliveryTime = jobDto.JobDetails.DeliveryTime;
    bool isLongTerm        = jobDto.JobDetails.LongTermStorage;

    // 2) predicates
    bool DateWindow(ZonePricingRuleDto r) =>
        r.ValidStartDate <= pickupDate
        && (isLongTerm || r.ValidEndDate >= deliveryDate);

    bool DayMatch(ZonePricingRuleDto r)
    {
        var days = r.OnDays
                    .Split(',', StringSplitOptions.RemoveEmptyEntries)
                    .Select(d => d.Trim());
        bool pickOk = days.Contains(pickupDay, StringComparer.OrdinalIgnoreCase);
        bool dropOk = isLongTerm
                      || days.Contains(deliveryDay, StringComparer.OrdinalIgnoreCase);
        return pickOk && dropOk;
    }

    bool TimeMatch(ZonePricingRuleDto r)
    {
        if (pickupTime is TimeOnly p
            && (p < r.ValidHoursStart || p > r.ValidHoursEnd))
        {
            return false;
        }
        if (!isLongTerm
            && deliveryTime is TimeOnly d
            && (d < r.ValidHoursStart || d > r.ValidHoursEnd))
        {
            return false;
        }
        return true;
    }

    // 3) stage 1: filter by date window
    var dateMatches = pricingZone.ZonePricingRuleCollection
        .Where(DateWindow);

    // 4) stage 2: filter by day-of-week
    var dayMatches = dateMatches
        .Where(DayMatch);

    // 5) stage 3: filter by time window
    var timeMatches = dayMatches
        .Where(TimeMatch);

    // 6) return the single matching rule (or null if none)
    return timeMatches.FirstOrDefault();
}
```

