## 4) Reality check you’ll hit once
- **Windows Firewall**: you’ll need an inbound rule for UDP `45678` (or whatever you choose), or your server won’t hear broadcasts.

That’s the whole server-side. If you want, I’ll sketch the matching client flow (broadcast → parse response → verify `/health` → write settings.json).

```csharp
// Program.cs
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllers();
builder.Services.Configure<DiscoveryOptions>(builder.Configuration.GetSection("Discovery"));

var app = builder.Build();

app.MapControllers();

app.Run();

public sealed class DiscoveryOptions
{
    // What clients should use to reach THIS API
    public string ApiScheme { get; set; } = "http";
    public string ApiHost { get; set; } = "192.168.1.16";
    public int ApiPort { get; set; } = 7071;
    public string ApiPrefix { get; set; } = "api";

    // What clients should use to reach SignalR
    public string SignalRScheme { get; set; } = "ws";
    public string SignalRHost { get; set; } = "192.168.1.16";
    public int SignalRPort { get; set; } = 5072;

    // Two “connection types” (either two hubs, or two register targets)
    public string DesktopHubPath { get; set; } = "/hubs/desktop";
