                    HubUrl = $"{signalRBase}{NormalizePath(_opt.DesktopHubPath)}",
                    RegisterMethod = _opt.DesktopRegisterMethod
                },

                ServerManager = new ClientConnectionDto
                {
                    ClientType = "ServerManager",
                    HubUrl = $"{signalRBase}{NormalizePath(_opt.ServerManagerHubPath)}",
                    RegisterMethod = _opt.ServerManagerRegisterMethod
                }
            };

            return Ok(dto);
        }

        // GET /api/discovery/client/desktop   OR   /api/discovery/client/servermanager
        [HttpGet("client/{clientType}")]
        [ProducesResponseType(typeof(ClientConnectionDto), 200)]
        [ProducesResponseType(404)]
        public ActionResult<ClientConnectionDto> GetClient(string clientType)
        {
            var signalRBase = $"{_opt.SignalRScheme}://{_opt.SignalRHost}:{_opt.SignalRPort}";

            if (clientType.Equals("desktop", StringComparison.OrdinalIgnoreCase))
            {
                return Ok(new ClientConnectionDto
                {
                    ClientType = "Desktop",
                    HubUrl = string.IsNullOrWhiteSpace(_opt.SingleHubPath)
                        ? $"{signalRBase}{NormalizePath(_opt.DesktopHubPath)}"
                        : $"{signalRBase}{NormalizePath(_opt.SingleHubPath)}",
                    RegisterMethod = _opt.DesktopRegisterMethod
                });
            }

            if (clientType.Equals("servermanager", StringComparison.OrdinalIgnoreCase) ||
                clientType.Equals("server-manager", StringComparison.OrdinalIgnoreCase) ||
                clientType.Equals("manager", StringComparison.OrdinalIgnoreCase))
            {
                return Ok(new ClientConnectionDto
                {
                    ClientType = "ServerManager",
                    HubUrl = string.IsNullOrWhiteSpace(_opt.SingleHubPath)
                        ? $"{signalRBase}{NormalizePath(_opt.ServerManagerHubPath)}"
                        : $"{signalRBase}{NormalizePath(_opt.SingleHubPath)}",
                    RegisterMethod = _opt.ServerManagerRegisterMethod
                });
            }

            return NotFound($"Unknown clientType '{clientType}'. Use 'desktop' or 'servermanager'.");
        }

        private static string NormalizePath(string? path)
        {
            if (string.IsNullOrWhiteSpace(path)) return "";
            path = path.Trim();
            if (!path.StartsWith("/")) path = "/" + path;
            return path;
        }
