```csharp
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

public sealed class UdpDiscoveryResponder : BackgroundService
{
    private const string DISCOVERY_PING = "LOGISTIX_DISCOVERY_V1";

    private readonly ILogger<UdpDiscoveryResponder> _log;
    private readonly DiscoveryOptions _opt;

    public UdpDiscoveryResponder(
        ILogger<UdpDiscoveryResponder> log,
        IOptions<DiscoveryOptions> options)
    {
        _log = log;
        _opt = options.Value;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        using var udp = new UdpClient(AddressFamily.InterNetwork);
        udp.EnableBroadcast = true;
        udp.Client.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReuseAddress, true);
        udp.Client.Bind(new IPEndPoint(IPAddress.Any, _opt.UdpPort));

        _log.LogInformation("UDP Discovery listening on 0.0.0.0:{Port}", _opt.UdpPort);

        while (!stoppingToken.IsCancellationRequested)
        {
            UdpReceiveResult recv;
            try
            {
                recv = await udp.ReceiveAsync(stoppingToken);
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (Exception ex)
            {
                _log.LogWarning(ex, "UDP discovery receive error");
                continue;
            }

            try
            {
                var text = Encoding.UTF8.GetString(recv.Buffer).Trim();

                // Accept either exact ping or ping with extra info (e.g., "LOGISTIX_DISCOVERY_V1|anything")
                if (!text.StartsWith(DISCOVERY_PING, StringComparison.OrdinalIgnoreCase))
                    continue;

                var response = BuildResponse();

                var json = JsonSerializer.Serialize(response, new JsonSerializerOptions
                {
                    WriteIndented = false
                });

                var bytes = Encoding.UTF8.GetBytes(json);
                await udp.SendAsync(bytes, bytes.Length, recv.RemoteEndPoint);

                _log.LogInformation("UDP discovery replied to {Client}", recv.RemoteEndPoint);
            }
            catch (Exception ex)
            {
                _log.LogDebug(ex, "UDP discovery request handling failed");
            }
        }

        _log.LogInformation("UDP Discovery stopped");
    }

    private DiscoveryProfileDto BuildResponse()
    {
        var apiBase = $"{_opt.ApiScheme}://{_opt.ApiHost}:{_opt.ApiPort}";
        var apiRoot = string.IsNullOrWhiteSpace(_opt.ApiPrefix)
            ? apiBase
            : $"{apiBase}/{_opt.ApiPrefix.Trim('/')}";

        var signalBase = $"{_opt.SignalRScheme}://{_opt.SignalRHost}:{_opt.SignalRPort}";

        return new DiscoveryProfileDto
        {
            Type = "LOGISTIX_DISCOVERY_RESPONSE_V1",
            Product = _opt.Product,
            Version = _opt.Version,
            Utc = DateTimeOffset.UtcNow.ToString("O"),

            ApiBaseUrl = apiBase,
            ApiRootUrl = apiRoot,
            ApiPrefix = _opt.ApiPrefix ?? "",

            SignalRBaseUrl = signalBase,

            Desktop = new ClientConnectionDto
            {
                ClientType = "Desktop",
                HubUrl = $"{signalBase}{NormalizePath(_opt.DesktopHubPath)}"
            },

            ServerManager = new ClientConnectionDto
            {
                ClientType = "ServerManager",
                HubUrl = $"{signalBase}{NormalizePath(_opt.ServerManagerHubPath)}"
            }
        };
    }

    private static string NormalizePath(string path)
    {
        path = (path ?? "").Trim();
        if (path.Length == 0) return "";
        if (!path.StartsWith("/")) path = "/" + path;
        return path;
    }

    private sealed class DiscoveryProfileDto
    {
        public string Type { get; set; } = "";
        public string Product { get; set; } = "";
        public string Version { get; set; } = "";
        public string Utc { get; set; } = "";

        public string ApiBaseUrl { get; set; } = "";
        public string ApiRootUrl { get; set; } = "";
        public string ApiPrefix { get; set; } = "";

        public string SignalRBaseUrl { get; set; } = "";

        public ClientConnectionDto Desktop { get; set; } = new();
        public ClientConnectionDto ServerManager { get; set; } = new();
    }

    private sealed class ClientConnectionDto
    {
        public string ClientType { get; set; } = "";
        public string HubUrl { get; set; } = "";
    }
}
