                    repo = await WithTimeout(
                        () => _settingsViewModel.LoadingEntryPoint(),
                        5000);
                }
                else
                {
                    await FadeIn(lblStatus, "....Retrying....");

                    // RETRY: 15s timeout
                    repo = await WithTimeout(
                        () => _settingsViewModel.LoadingEntryPoint(),
                        15000);
                }

                // IMPORTANT: WithTimeout now returns the *real* ViewModelResult from LoadingEntryPoint.
                if (repo != null && repo.Success)
                {
                    await FadeIn(lblStatus, "Data Synced - Application will restart", 400);
                    Application.Restart();
                    return;
                }

                await FadeIn(lblStatus, "MCP Not Found - Check Server & Firewall Port 9876");
                btnRetry.Visible = true;
                btnRetry.Enabled = true;
            }
            catch (Exception ex)
            {
                await FadeIn(lblStatus, $"Error: {ex.Message}");
                btnRetry.Visible = true;
                btnRetry.Enabled = true;
            }
            finally
            {
                _isRunning = false;
            }
        }

        // ---------------------------------------------------------
        // TIMEOUT WRAPPER (RETURNS THE REAL RESULT)
        // ---------------------------------------------------------
        public async Task<ViewModelResult> WithTimeout(Func<Task<ViewModelResult>> operation, int milliseconds)
        {
            // start a NEW operation task each time this is called
            Task<ViewModelResult> opTask;

            try
            {
                opTask = operation();
                if (opTask == null)
                {
                    return new ViewModelResult
                    {
                        Success = false,
                        Message = "Operation returned null task."
                    };
                }
            }
            catch (Exception ex)
            {
                return new ViewModelResult
                {
                    Success = false,
                    Message = ex.Message
                };
            }

            var timeoutTask = Task.Delay(milliseconds);
            var completed = await Task.WhenAny(opTask, timeoutTask);

            if (completed == timeoutTask)
            {
                // observe exceptions later so you don't get unobserved task exceptions
                _ = opTask.ContinueWith(t =>
                {
                    try { _ = t.Exception; } catch { }
                }, TaskContinuationOptions.OnlyOnFaulted);

                return new ViewModelResult
                {
                    Success = false,
                    Message = "Operation timed out."
                };
            }

            // completed = opTask
            try
            {
                return await opTask; // <-- this is the key fix (don’t invent Success=true)
            }
            catch (Exception ex)
            {
                return new ViewModelResult
                {
                    Success = false,
                    Message = ex.Message
                };
            }
        }

