        {
            InitializeComponent();

            _settingsViewModel = settingsViewModel;
            StartPosition = FormStartPosition.CenterScreen;

            btnRetry.Visible = false;
            btnRetry.Enabled = true;
            btnRetry.Click += BtnRetry_Click;

            Shown += OnShown;
        }

        private async void OnShown(object sender, EventArgs e)
        {
            Shown -= OnShown; // one-time
            await RunStartupSequence(skipIntro: false);
        }

        private async void BtnRetry_Click(object sender, EventArgs e)
        {
            if (_isRunning) return;

            btnRetry.Visible = false;
            btnRetry.Enabled = false;

            await RunStartupSequence(skipIntro: true);
        }

        // ---------------------------------------------------------
        // MAIN STARTUP SEQUENCE
        // ---------------------------------------------------------
        private async Task RunStartupSequence(bool skipIntro = false)
        {
            if (_isRunning) return;
            _isRunning = true;

            try
            {
                ViewModelResult repo;

                if (!skipIntro)
                {
                    await FadeInOut(lblStatus, "Hello");
                    await FadeInOut(lblStatus, "Welcome to Logistixs");
                    await FadeInOut(lblStatus, "Searching for MCP Beacon");
                    await FadeIn(lblStatus, "....Searching....");

                    // FIRST RUN: search window of 5s, retry every 1s
                    repo = await TryForWindow(
                        () => _settingsViewModel.LoadingEntryPoint(),
                        windowMs: 5000,
                        attemptIntervalMs: 1000);
                }
                else
                {
                    await FadeIn(lblStatus, "....Retrying....");

                    // RETRY: search window of 15s, retry every 1s
                    repo = await TryForWindow(
                        () => _settingsViewModel.LoadingEntryPoint(),
                        windowMs: 15000,
                        attemptIntervalMs: 1000);
                }

                if (repo != null && repo.Success)
                {
                    await FadeIn(lblStatus, "Data Synced - Application will restart", 400);
                    Application.Restart();
                    return;
                }

                await FadeIn(lblStatus, "MCP Not Found - Check Server & Firewall Port 9876");
                btnRetry.Visible = true;
                btnRetry.Enabled = true;
            }
            catch (Exception ex)
            {
                await FadeIn(lblStatus, $"Error: {ex.Message}");
                btnRetry.Visible = true;
                btnRetry.Enabled = true;
            }
            finally
            {
                _isRunning = false;
            }
        }

        // ---------------------------------------------------------
        // SEARCH WINDOW: keep trying for N ms (prevents instant bounce)
        // ---------------------------------------------------------
        private async Task<ViewModelResult> TryForWindow(
            Func<Task<ViewModelResult>> attempt,
            int windowMs,
            int attemptIntervalMs)
        {
            var sw = Stopwatch.StartNew();
            ViewModelResult last = null;

            while (sw.ElapsedMilliseconds < windowMs)
            {
                last = await SafeAttempt(attempt);

                if (last != null && last.Success)
                    return last;

                var remaining = windowMs - (int)sw.ElapsedMilliseconds;
                if (remaining <= 0)
                    break;

                await Task.Delay(Math.Min(attemptIntervalMs, remaining));
            }

            return last ?? new ViewModelResult
            {
                Success = false,
                Message = "MCP Not Found."
            };
        }

        private async Task<ViewModelResult> SafeAttempt(Func<Task<ViewModelResult>> attempt)
        {
            try
            {
                var res = await attempt();
                return res ?? new ViewModelResult { Success = false, Message = "Null result." };
            }
            catch (Exception ex)
            {
                return new ViewModelResult { Success = false, Message = ex.Message };
            }
        }

        // ---------------------------------------------------------
        // UI ANIMATIONS
        // ---------------------------------------------------------
        private async Task FadeInOut(RadLabel lbl, string newText, int durationMs = 400, int hold = 2000)
        {
            if (lbl == null || lbl.IsDisposed) return;

            lbl.Text = newText;
            var baseColor = lbl.ForeColor;
            lbl.ForeColor = Color.FromArgb(0, baseColor);
            lbl.Refresh();

            int steps = 20;
            int delay = durationMs / steps;

            for (int i = 0; i <= steps; i++)
            {
                int alpha = (int)(255 * (i / (float)steps));
                lbl.ForeColor = Color.FromArgb(alpha, baseColor);
                await Task.Delay(delay);
            }

            await Task.Delay(hold);

            for (int i = steps; i >= 0; i--)
            {
                int alpha = (int)(255 * (i / (float)steps));
                lbl.ForeColor = Color.FromArgb(alpha, baseColor);
                await Task.Delay(delay);
            }

            await Task.Delay(800);
            lbl.Text = "";
            lbl.ForeColor = baseColor;
            lbl.Refresh();
        }

        private async Task FadeIn(RadLabel lbl, string newText, int durationMs = 400)
        {
            if (lbl == null || lbl.IsDisposed) return;

            lbl.Text = newText;
