    public abstract class BaseCreateUseCase<TRepo, TDto>
        where TRepo : IBaseApiRepository<TDto>
        where TDto : BaseEntity
    {
        protected readonly TRepo Repo;

        protected BaseCreateUseCase(TRepo repo)
        {
            Repo = repo ?? throw new ArgumentNullException(nameof(repo));
        }

        public virtual Task<EntityPackage<TDto>> CreateAsync(TDto dto, CancellationToken ct = default)
