using Logistix.Domain.Models.Base;
using Logistix.Domain.Models.ReturnTypes;
using Logistix.Domain.Ports;
using System;
using System.Threading;
using System.Threading.Tasks;

namespace Logistix.ApplicationLayer.UseCase.Base
{
    public abstract class BaseCreateUseCase<TRepo, TEntity>
        where TRepo : IBaseApiRepository<TEntity>
        where TEntity : BaseEntity
    {
        protected readonly TRepo Repo;

        protected BaseCreateUseCase(TRepo repo)
        {
            Repo = repo ?? throw new ArgumentNullException(nameof(repo));
        }

        // Default create path: calls Repo.CreateAsync
        public virtual Task<EntityPackage<TEntity>> CreateAsync(TEntity entity, CancellationToken ct = default)
        {
            return Repo.CreateAsync(entity, ct);
        }
    }
}
